#!/usr/bin/env python3
"""
Global Intentional Homicide Trends Report Generator
Analyzes UNODC homicide data and produces a comprehensive HTML report.
"""

import pandas as pd
import numpy as np
import json
from datetime import datetime
import warnings
warnings.filterwarnings('ignore')

# Load data
print("Loading data...")
df = pd.read_csv('/app/benchmark/data.csv')
print(f"Loaded {len(df)} rows, {df['year'].min()}–{df['year'].max()}")

# Filter for overall rates (both sexes, all ages) for main analysis
df_all = df[(df['sex'] == 'both') & (df['age_group'] == 'ALL')].copy()

# =============================================================================
# KPI CALCULATIONS
# =============================================================================

print("Calculating KPIs...")

# Most recent year with data
most_recent_year = df_all['year'].max()
print(f"Most recent year with data: {most_recent_year}")

# Global Median Homicide Rate (most recent year)
median_rate_recent = df_all[df_all['year'] == most_recent_year]['homicide_rate'].median()

# Countries reporting in most recent year
countries_recent = df_all[df_all['year'] == most_recent_year]['country'].nunique()

# Male-to-Female Homicide Rate Ratio
df_male = df[(df['sex'] == 'male') & (df['age_group'] == 'ALL')]
df_female = df[(df['sex'] == 'female') & (df['age_group'] == 'ALL')]

# Global male and female rates for most recent year (by merging)
male_recent = df_male[df_male['year'] == most_recent_year].groupby('country')['homicide_rate'].mean()
female_recent = df_female[df_female['year'] == most_recent_year].groupby('country')['homicide_rate'].mean()

# Ratio of global means
male_mean = male_recent.mean()
female_mean = female_recent.mean()
male_female_ratio = male_mean / female_mean if female_mean > 0 else np.nan

# Highest National Homicide Rate (most recent year)
highest_rate_row = df_all[df_all['year'] == most_recent_year].loc[
    df_all[df_all['year'] == most_recent_year]['homicide_rate'].idxmax()
]
highest_country = highest_rate_row['country']
highest_rate = highest_rate_row['homicide_rate']

# Decade-over-Decade Change
decades = {
    '1990s': (1990, 1999),
    '2000s': (2000, 2009),
    '2010s': (2010, 2019),
    '2020s': (2020, 2023)
}

decade_averages = {}
for decade_name, (start, end) in decades.items():
    decade_data = df_all[(df_all['year'] >= start) & (df_all['year'] <= end)]
    decade_averages[decade_name] = decade_data['homicide_rate'].mean()

# Calculate changes
change_90s_00s = ((decade_averages['2000s'] - decade_averages['1990s']) / decade_averages['1990s']) * 100
change_00s_10s = ((decade_averages['2010s'] - decade_averages['2000s']) / decade_averages['2000s']) * 100
change_10s_20s = ((decade_averages['2020s'] - decade_averages['2010s']) / decade_averages['2010s']) * 100

# Reporting Coverage Rate (proportion of countries with data each year)
all_countries = df_all['country'].nunique()
coverage_by_year = df_all.groupby('year')['country'].nunique() / all_countries * 100
avg_coverage = coverage_by_year.mean()

# =============================================================================
# GLOBAL OVERVIEW DATA
# =============================================================================

print("Computing global trends...")

# Year-by-year global statistics
yearly_stats = df_all.groupby('year').agg({
    'homicide_rate': ['mean', 'median', 'std', 'count'],
    'country': 'nunique'
}).reset_index()
yearly_stats.columns = ['year', 'mean_rate', 'median_rate', 'std_rate', 'n_records', 'n_countries']

# =============================================================================
# REGIONAL COMPARISON DATA
# =============================================================================

print("Computing regional comparisons...")

# Define regions based on ISO codes mapping
region_mapping = {
    # Europe
    'ALB': 'Europe', 'AND': 'Europe', 'AUT': 'Europe', 'BLR': 'Europe', 'BEL': 'Europe',
    'BIH': 'Europe', 'BGR': 'Europe', 'HRV': 'Europe', 'CYP': 'Europe', 'CZE': 'Europe',
    'DNK': 'Europe', 'EST': 'Europe', 'FIN': 'Europe', 'FRA': 'Europe', 'DEU': 'Europe',
    'GRC': 'Europe', 'HUN': 'Europe', 'ISL': 'Europe', 'IRL': 'Europe', 'ITA': 'Europe',
    'XKX': 'Europe', 'LVA': 'Europe', 'LIE': 'Europe', 'LTU': 'Europe', 'LUX': 'Europe',
    'MKD': 'Europe', 'MLT': 'Europe', 'MDA': 'Europe', 'MCO': 'Europe', 'MNE': 'Europe',
    'NLD': 'Europe', 'NOR': 'Europe', 'POL': 'Europe', 'PRT': 'Europe', 'ROU': 'Europe',
    'RUS': 'Europe', 'SMR': 'Europe', 'SRB': 'Europe', 'SVK': 'Europe', 'SVN': 'Europe',
    'ESP': 'Europe', 'SWE': 'Europe', 'CHE': 'Europe', 'UKR': 'Europe', 'GBR': 'Europe',
    'GBR': 'Europe',  # England & Wales (UK)

    # Americas
    'ARG': 'Americas', 'ABW': 'Americas', 'BHS': 'Americas', 'BRB': 'Americas', 'BLZ': 'Americas',
    'BOL': 'Americas', 'BRA': 'Americas', 'CAN': 'Americas', 'CHL': 'Americas', 'COL': 'Americas',
    'CRI': 'Americas', 'CUB': 'Americas', 'CUW': 'Americas', 'DMA': 'Americas', 'DOM': 'Americas',
    'ECU': 'Americas', 'SLV': 'Americas', 'GRD': 'Americas', 'GTM': 'Americas', 'GUY': 'Americas',
    'HTI': 'Americas', 'HND': 'Americas', 'JAM': 'Americas', 'MEX': 'Americas', 'NIC': 'Americas',
    'PAN': 'Americas', 'PRY': 'Americas', 'PER': 'Americas', 'PRI': 'Americas', 'KNA': 'Americas',
    'LCA': 'Americas', 'MAF': 'Americas', 'VCT': 'Americas', 'SXM': 'Americas', 'TTO': 'Americas',
    'TCA': 'Americas', 'USA': 'Americas', 'URY': 'Americas', 'VEN': 'Americas', 'VIR': 'Americas',

    # Asia
    'AFG': 'Asia', 'ARM': 'Asia', 'AZE': 'Asia', 'BHR': 'Asia', 'BGD': 'Asia',
    'BTN': 'Asia', 'BRN': 'Asia', 'KHM': 'Asia', 'CHN': 'Asia', 'CYP': 'Asia',
    'GEO': 'Asia', 'HKG': 'Asia', 'IND': 'Asia', 'IDN': 'Asia', 'IRN': 'Asia',
    'IRQ': 'Asia', 'ISR': 'Asia', 'JPN': 'Asia', 'JOR': 'Asia', 'KAZ': 'Asia',
    'KWT': 'Asia', 'KGZ': 'Asia', 'LAO': 'Asia', 'LBN': 'Asia', 'MAC': 'Asia',
    'MYS': 'Asia', 'MNG': 'Asia', 'MMR': 'Asia', 'NPL': 'Asia', 'PRK': 'Asia',
    'OMN': 'Asia', 'PAK': 'Asia', 'PSE': 'Asia', 'PHL': 'Asia', 'QAT': 'Asia',
    'SAU': 'Asia', 'SGP': 'Asia', 'KOR': 'Asia', 'LKA': 'Asia', 'SYR': 'Asia',
    'TWN': 'Asia', 'TJK': 'Asia', 'THA': 'Asia', 'TLS': 'Asia', 'TUR': 'Asia',
    'TKM': 'Asia', 'ARE': 'Asia', 'UZB': 'Asia', 'VNM': 'Asia', 'YEM': 'Asia',

    # Africa
    'DZA': 'Africa', 'AGO': 'Africa', 'BEN': 'Africa', 'BWA': 'Africa', 'BFA': 'Africa',
    'BDI': 'Africa', 'CMR': 'Africa', 'CPV': 'Africa', 'CAF': 'Africa', 'TCD': 'Africa',
    'COM': 'Africa', 'COG': 'Africa', 'COD': 'Africa', 'CIV': 'Africa', 'DJI': 'Africa',
    'EGY': 'Africa', 'GNQ': 'Africa', 'ERI': 'Africa', 'SWZ': 'Africa', 'ETH': 'Africa',
    'GAB': 'Africa', 'GMB': 'Africa', 'GHA': 'Africa', 'GIN': 'Africa', 'GNB': 'Africa',
    'KEN': 'Africa', 'LSO': 'Africa', 'LBR': 'Africa', 'LBY': 'Africa', 'MDG': 'Africa',
    'MWI': 'Africa', 'MLI': 'Africa', 'MRT': 'Africa', 'MUS': 'Africa', 'MAR': 'Africa',
    'MOZ': 'Africa', 'NAM': 'Africa', 'NER': 'Africa', 'NGA': 'Africa', 'RWA': 'Africa',
    'STP': 'Africa', 'SEN': 'Africa', 'SYC': 'Africa', 'SLE': 'Africa', 'SOM': 'Africa',
    'ZAF': 'Africa', 'SSD': 'Africa', 'SDN': 'Africa', 'TZA': 'Africa', 'TGO': 'Africa',
    'TUN': 'Africa', 'UGA': 'Africa', 'ZMB': 'Africa', 'ZWE': 'Africa',

    # Oceania
    'AUS': 'Oceania', 'FJI': 'Oceania', 'KIR': 'Oceania', 'MHL': 'Oceania', 'FSM': 'Oceania',
    'NRU': 'Oceania', 'NZL': 'Oceania', 'PLW': 'Oceania', 'PNG': 'Oceania', 'WSM': 'Oceania',
    'SLB': 'Oceania', 'TON': 'Oceania', 'TUV': 'Oceania', 'VUT': 'Oceania'
}

df_all['region'] = df_all['iso_code'].map(region_mapping).fillna('Other')

# Top 10 and Bottom 10 countries (most recent year)
recent_data = df_all[df_all['year'] == most_recent_year].copy()
recent_data = recent_data.sort_values('homicide_rate', ascending=False)

top_10 = recent_data.head(10)[['country', 'homicide_rate', 'region']]
bottom_10 = recent_data.tail(10)[['country', 'homicide_rate', 'region']].iloc[::-1]

# Regional averages (most recent year)
regional_recent = recent_data.groupby('region')['homicide_rate'].agg(['mean', 'median', 'count']).reset_index()
regional_recent = regional_recent.sort_values('mean', ascending=False)

# =============================================================================
# GENDER DISPARITY DATA
# =============================================================================

print("Computing gender disparity...")

# Male/female ratio over time
years_gender = sorted(df_male['year'].unique())
gender_ratio_by_year = []

for year in years_gender:
    male_avg = df_male[df_male['year'] == year]['homicide_rate'].mean()
    female_data = df_female[df_female['year'] == year]
    if len(female_data) > 0:
        female_avg = female_data['homicide_rate'].mean()
        if female_avg > 0:
            ratio = male_avg / female_avg
            gender_ratio_by_year.append({'year': year, 'ratio': ratio, 'male_rate': male_avg, 'female_rate': female_avg})

gender_df = pd.DataFrame(gender_ratio_by_year)

# Countries with highest male/female ratio (most recent)
male_by_country = df_male[df_male['year'] == most_recent_year].set_index('country')['homicide_rate']
female_by_country = df_female[df_female['year'] == most_recent_year].set_index('country')['homicide_rate']

common_countries = male_by_country.index.intersection(female_by_country.index)
ratio_by_country = (male_by_country[common_countries] / female_by_country[common_countries]).sort_values(ascending=False)

top_gender_disparity = ratio_by_country.head(10)

# =============================================================================
# AGE GROUP ANALYSIS
# =============================================================================

print("Computing age group analysis...")

# Filter for specific age groups (not ALL)
df_age = df[(df['sex'] == 'both') & (df['age_group'] != 'ALL')].copy()

# Get all age groups present
age_groups = df_age['age_group'].unique()

# Global average by age group (most recent year)
age_recent = df_age[df_age['year'] == most_recent_year]
age_avg = age_recent.groupby('age_group')['homicide_rate'].mean().sort_values(ascending=False)

# Highest risk age groups over time
age_by_year = df_age.groupby(['year', 'age_group'])['homicide_rate'].mean().reset_index()

# =============================================================================
# NOTABLE TRENDS & OUTLIERS
# =============================================================================

print("Computing notable trends...")

# Calculate country-level trends (slope of homicide rate over time)
from scipy import stats

country_trends = []
for country in df_all['country'].unique():
    country_data = df_all[df_all['country'] == country].sort_values('year')
    if len(country_data) >= 5:  # Need at least 5 data points
        years = country_data['year'].values
        rates = country_data['homicide_rate'].values
        slope, intercept, r_value, p_value, std_err = stats.linregress(years, rates)
        first_rate = rates[0]
        last_rate = rates[-1]
        pct_change = ((last_rate - first_rate) / first_rate) * 100 if first_rate > 0 else np.nan
        country_trends.append({
            'country': country,
            'slope': slope,
            'pct_change': pct_change,
            'first_year': years[0],
            'last_year': years[-1],
            'first_rate': first_rate,
            'last_rate': last_rate,
            'n_years': len(country_data)
        })

trends_df = pd.DataFrame(country_trends)

# Countries with biggest improvements (negative slope)
improvers = trends_df[trends_df['slope'] < 0].sort_values('slope').head(10)

# Countries with biggest deteriorations (positive slope)
deteriorators = trends_df[trends_df['slope'] > 0].sort_values('slope', ascending=False).head(10)

# Statistical outliers (countries with extreme rates)
rate_mean = recent_data['homicide_rate'].mean()
rate_std = recent_data['homicide_rate'].std()
recent_data['z_score'] = (recent_data['homicide_rate'] - rate_mean) / rate_std
outliers = recent_data[abs(recent_data['z_score']) > 2][['country', 'homicide_rate', 'z_score']]

# =============================================================================
# GENERATE HTML REPORT
# =============================================================================

print("Generating HTML report...")

html_content = f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Global Intentional Homicide Trends: A Multi-Dimensional Analysis (1990–2023)</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <style>
        :root {{
            --primary: #1a365d;
            --secondary: #2c5282;
            --accent: #e53e3e;
            --success: #38a169;
            --warning: #d69e2e;
            --bg-light: #f7fafc;
            --bg-white: #ffffff;
            --text-dark: #1a202c;
            --text-gray: #4a5568;
            --border: #e2e8f0;
        }}

        * {{
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }}

        body {{
            font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, 'Helvetica Neue', Arial, sans-serif;
            line-height: 1.6;
            color: var(--text-dark);
            background: var(--bg-light);
        }}

        .container {{
            max-width: 1200px;
            margin: 0 auto;
            padding: 20px;
        }}

        /* Header */
        header {{
            background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
            color: white;
            padding: 40px 20px;
            margin-bottom: 30px;
        }}

        header h1 {{
            font-size: 2.2rem;
            font-weight: 700;
            margin-bottom: 10px;
        }}

        header .subtitle {{
            font-size: 1.1rem;
            opacity: 0.9;
        }}

        header .meta {{
            margin-top: 15px;
            font-size: 0.9rem;
            opacity: 0.8;
        }}

        /* KPI Dashboard */
        .kpi-dashboard {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
            gap: 20px;
            margin-bottom: 40px;
        }}

        .kpi-card {{
            background: var(--bg-white);
            border-radius: 12px;
            padding: 24px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.08);
            border-left: 4px solid var(--secondary);
        }}

        .kpi-card.highlight {{
            border-left-color: var(--accent);
        }}

        .kpi-card.success {{
            border-left-color: var(--success);
        }}

        .kpi-label {{
            font-size: 0.85rem;
            color: var(--text-gray);
            text-transform: uppercase;
            letter-spacing: 0.5px;
            margin-bottom: 8px;
        }}

        .kpi-value {{
            font-size: 2rem;
            font-weight: 700;
            color: var(--primary);
        }}

        .kpi-sub {{
            font-size: 0.85rem;
            color: var(--text-gray);
            margin-top: 5px;
        }}

        /* Sections */
        .section {{
            background: var(--bg-white);
            border-radius: 12px;
            padding: 30px;
            margin-bottom: 30px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.08);
        }}

        .section h2 {{
            font-size: 1.5rem;
            color: var(--primary);
            margin-bottom: 20px;
            padding-bottom: 10px;
            border-bottom: 2px solid var(--border);
        }}

        .section h3 {{
            font-size: 1.1rem;
            color: var(--secondary);
            margin: 20px 0 10px;
        }}

        .section p {{
            margin-bottom: 15px;
            color: var(--text-gray);
        }}

        /* Charts */
        .chart-container {{
            position: relative;
            height: 350px;
            margin: 20px 0;
        }}

        .chart-container.small {{
            height: 280px;
        }}

        /* Tables */
        table {{
            width: 100%;
            border-collapse: collapse;
            margin: 15px 0;
        }}

        th, td {{
            padding: 12px 15px;
            text-align: left;
            border-bottom: 1px solid var(--border);
        }}

        th {{
            background: var(--bg-light);
            font-weight: 600;
            color: var(--primary);
        }}

        tr:hover {{
            background: var(--bg-light);
        }}

        .rate-high {{
            color: var(--accent);
            font-weight: 600;
        }}

        .rate-low {{
            color: var(--success);
            font-weight: 600;
        }}

