# Calculate country-level trends (slope of homicide rate over time)
from scipy import stats

country_trends = []
for country in df_all['country'].unique():
    country_data = df_all[df_all['country'] == country].sort_values('year')
    if len(country_data) >= 5:  # Need at least 5 data points
        years = country_data['year'].values
        rates = country_data['homicide_rate'].values
        slope, intercept, r_value, p_value, std_err = stats.linregress(years, rates)
        first_rate = rates[0]
        last_rate = rates[-1]
        pct_change = ((last_rate - first_rate) / first_rate) * 100 if first_rate > 0 else np.nan
        country_trends.append({
            'country': country,
            'slope': slope,
            'pct_change': pct_change,
            'first_year': years[0],
            'last_year': years[-1],
            'first_rate': first_rate,
            'last_rate': last_rate,
            'n_years': len(country_data)
        })

