#!/usr/bin/env python3
"""
Global Intentional Homicide Trends Report Generator
Analyzes UNODC homicide data and produces a comprehensive HTML report.
"""

import pandas as pd
import numpy as np
import json
from datetime import datetime
import warnings
warnings.filterwarnings('ignore')

# Load data
print("Loading data...")
df = pd.read_csv('/app/benchmark/data.csv')
print(f"Loaded {len(df)} rows, {df['year'].min()}–{df['year'].max()}")

# Filter for overall rates (both sexes, all ages) for main analysis
df_all = df[(df['sex'] == 'both') & (df['age_group'] == 'ALL')].copy()

# =============================================================================
# KPI CALCULATIONS
# =============================================================================

print("Calculating KPIs...")

# Most recent year with data
most_recent_year = df_all['year'].max()
print(f"Most recent year with data: {most_recent_year}")

# Global Median Homicide Rate (most recent year)
